    static GameCheck Exact(string name, string[] entries, Func<SpellLog, Projection, string?> failure) =>
        new(name, run => failure(new SpellLog(run.EffectiveLog), run.Final), entries);

    static string Faces(IEnumerable<Die> dice) => $"[{string.Join(",", dice.Select(d => d.Raw))}]";

    /// <summary>Every casting roll: one die; an unmodified 1 fails and an unmodified 6 succeeds whatever the modifiers, else 4+ after them.</summary>
    static string? CastingRolls(SpellLog log, Projection final)
    {
        var casts = log.Frames("casting").Select(f => log.Steps(f.FrameId).FirstOrDefault(s => s.Step == "roll")).OfType<StepCompleted>().ToList();
        if (casts.Count == 0) return "no casting roll";
        foreach (var step in casts)
        {
            var roll = step.Rolls.Single(r => r.Roll == "casting");
            if (roll.Dice.Count != 1) return $"a casting roll of {roll.Dice.Count} dice";
            var die = log.Dice(roll)[0];
            var expected = die.Raw != 1 && (die.Raw == 6 || die.Modified >= 4);
            var passed = step.Values?.GetValueOrDefault("passed") == 1;
            if (die.Success != expected || passed != expected)
                return $"raw {die.Raw}, modified {die.Modified} ({string.Join(", ", roll.Modifiers.Select(m => $"{m.Source} {m.Amount:+0;-0}"))}): "
                    + $"expected {(expected ? "a pass" : "a fail")}, the die says {(die.Success ? "success" : "failure")} and the cast {(passed ? "resolved" : "did not")}";
        }
        return null;
    }

    /// <summary>The spell-hits frames of a spell's resolved casts, each with its hit step and its resolve-hits' defense rolls.</summary>
    static IReadOnlyList<(SpellCast Cast, SequenceStarted Hits, StepCompleted Hit, IReadOnlyList<RollRecord> Defense)> SpellHits(SpellLog log, string spell) =>
        log.Casts(spell).Where(c => c.Passed).SelectMany(c => log.Children(c.Frame).Where(f => f.Sequence == "spell-hits").Select(h =>
        (c, h, log.Steps(h.FrameId).Single(s => s.Step == "hit"),
            (IReadOnlyList<RollRecord>)log.Children(h.FrameId).Where(r => r.Sequence == "resolve-hits")
                .SelectMany(r => log.Steps(r.FrameId)).Where(s => s.Step == "roll-to-block").SelectMany(s => s.Rolls).Where(r => r.Roll == "defense").ToList()))).ToList();

    /// <summary>Mutating Inferno: each target takes 4 hits, no die rolled for them; 4 blocks rolled; each failed block is a wound.</summary>
    static string? MutatingInferno(SpellLog log, Projection final)
    {
        var hits = SpellHits(log, "Mutating Inferno");
        if (hits.Count == 0) return "Mutating Inferno never resolved";
        foreach (var (cast, frame, hit, defense) in hits)
        {
            if (hit.Rolls.Count > 0) return $"the hits rolled {hit.Rolls.Count} rolls; the text rolls none";
            if (hit.Values?.GetValueOrDefault("hits") != 4) return $"hits {hit.Values?.GetValueOrDefault("hits")}, not 4";
            if (defense.Sum(r => r.Dice.Count) != 4) return $"{defense.Sum(r => r.Dice.Count)} blocks rolled for 4 hits";
            var failed = defense.Sum(r => log.Dice(r).Count(d => !d.Success));
            // An assign step repeats per model while wounds are left; its wounds_dealt is the frame's running total.
            var dealt = log.Descendants(frame.FrameId).Where(f => f.Sequence == "deal-wounds")
                .Sum(f => log.Steps(f.FrameId).LastOrDefault(s => s.Step == "assign")?.Values?.GetValueOrDefault("wounds_dealt") ?? 0);
            if (dealt != failed) return $"{failed} failed blocks ({string.Join(" ", defense.Select(r => Faces(log.Dice(r))))}) dealt {dealt} wounds";
        }
        return null;
    }

    /// <summary>Sky Blaze: 2 hits, one die each at no threshold to fail; each unmodified 6 adds a hit; every block is at AP(1).</summary>
    static string? SkyBlaze(SpellLog log, Projection final)
    {
        var hits = SpellHits(log, "Sky Blaze");
        if (hits.Count == 0) return "Sky Blaze never resolved";
        foreach (var (_, _, hit, defense) in hits)
        {
            var roll = hit.Rolls.SingleOrDefault(r => r.Roll == "hit");
            if (roll is null || roll.Dice.Count != 2) return $"rolled {roll?.Dice.Count ?? 0} dice for 2 hits";
            var dice = log.Dice(roll);
            if (dice.Any(d => !d.Success)) return $"a spell hit die failed: {Faces(dice)}";
            var sixes = dice.Count(d => d.Raw == 6);
            if (hit.Values?.GetValueOrDefault("extra_hits") != sixes) return $"{sixes} sixes {Faces(dice)} gave {hit.Values?.GetValueOrDefault("extra_hits")} extra hits";
            if (defense.Sum(r => r.Dice.Count) != 2 + sixes) return $"{defense.Sum(r => r.Dice.Count)} blocks rolled for {2 + sixes} hits";
            if (defense.FirstOrDefault(r => !r.Modifiers.Contains(new RollModifier("AP", -1))) is { } bare)
                return $"a block without AP -1: {string.Join(", ", bare.Modifiers)}";
        }
        return hits.Any(h => h.Hit.Values?.GetValueOrDefault("extra_hits") > 0) ? null : "no Sky Blaze rolled a 6; the seed must show Surge";
    }

    /// <summary>Breath of Change: one grant per target, on the caster's side, none for a target already holding the spell.</summary>
    static string? BreathOfChange(SpellLog log, Projection final)
    {
        var casts = log.Casts("Breath of Change").Where(c => c.Passed).ToList();
        if (casts.Count == 0) return "Breath of Change never resolved";
        foreach (var cast in casts)
        {
            var side = final.Units[cast.Unit].ParticipantId;
            if (cast.Targets.Any(t => final.Units[t].ParticipantId != side)) return "an enemy unit was a target";
            var grants = log.GrantsOf(cast);
            if (grants.Any(g => g.Grant.EntryName != "Breath of Change" || !cast.Targets.Contains(g.UnitId))) return "a grant off the targets or not of the spell";
            var at = log.StartOf(cast.Frame);
            foreach (var target in cast.Targets)
            {
                var held = Held(log, target, "Breath of Change", at);
                var written = grants.Count(g => g.UnitId == target);
                if (written != (held ? 0 : 1)) return $"{written} grants on a target that {(held ? "already held" : "did not hold")} the spell";
            }
        }
        return null;
    }

    /// <summary>Whether a unit holds a grant of that spell before a log index: added and not yet removed.</summary>
    static bool Held(SpellLog log, Guid unit, string spell, int before)
    {
        var live = new HashSet<Guid>();
        foreach (var step in log.Payloads.Take(before).OfType<StepCompleted>())
            foreach (var change in step.Changes)
                if (change is GrantAdded a && a.UnitId == unit && a.Grant.EntryName == spell) live.Add(a.Grant.Id);
                else if (change is GrantRemoved r && r.UnitId == unit) live.Remove(r.GrantId);
        return live.Count > 0;
    }

    /// <summary>The first grant of a spell, as (the step that wrote it, the grant).</summary>
    static (int At, GrantAdded Grant)? FirstGrant(SpellLog log, string spell, Func<GrantAdded, bool>? where = null)
    {
        for (var i = 0; i < log.Payloads.Count; i++)
            if (log.Payloads[i] is StepCompleted s && s.Changes.OfType<GrantAdded>().FirstOrDefault(g => g.Grant.EntryName == spell && (where?.Invoke(g) ?? true)) is { } g)
                return (i, g);
        return null;
    }

    /// <summary>Tech-Sickness: the target's next block roll is at -1, and that step spends the grant.</summary>
    static string? TechSickness(SpellLog log, Projection final)
    {
        if (FirstGrant(log, "Tech-Sickness") is not var (at, grant)) return "Tech-Sickness never granted";
        var block = log.Payloads.Skip(at + 1).OfType<StepCompleted>().FirstOrDefault(s => s.Step == "roll-to-block"
            && log.Frame(s.FrameId).Context.TargetUnitIds.FirstOrDefault() == grant.UnitId && s.Rolls.Any(r => r.Roll == "defense"));
        if (block is null) return "the target never rolled to block after the grant";
        var mods = block.Rolls.Where(r => r.Roll == "defense").SelectMany(r => r.Modifiers).Where(m => m.Source == "Tech-Sickness").ToList();
        if (mods.Count == 0 || mods.Any(m => m.Amount != -1)) return $"the next block's Tech-Sickness modifiers: [{string.Join(", ", mods.Select(m => m.Amount))}]";
        if (!block.Changes.OfType<GrantRemoved>().Any(r => r.GrantId == grant.Grant.Id)) return "the block that used the grant did not remove it";
        return null;
    }

    static readonly IReadOnlySet<string> RootActions = new HashSet<string> { "hold", "advance", "rush", "charge", "idle" };

    /// <summary>Shock Speed on a unit other than the caster's: the unit's next action move allows 6+2 on Advance, 12+4 on Rush and Charge.</summary>
    static string? ShockSpeed(SpellLog log, Projection final)
    {
        var casters = log.Casts("Shock Speed").Select(c => c.Unit).ToHashSet();
        if (FirstGrant(log, "Shock Speed", g => !casters.Contains(g.UnitId)) is not var (at, grant)) return "Shock Speed never granted to a unit other than its caster's";
        var models = final.Models.Values.Where(m => m.UnitId == grant.UnitId).Select(m => m.Id).ToHashSet();
        var ask = log.Payloads.Skip(at + 1).OfType<AskOpened>().Select(a => a.Ask).FirstOrDefault(a => a.Question == "move" && a.Legal is MoveRegion region
            && region.ModelIds.All(models.Contains) && a.FrameId is { } f && log.Frame(f).Sequence is "advance" or "rush" or "charge");
        if (ask is null) return "the unit never moved by an action after the grant";
        var action = log.Frame(ask.FrameId!.Value).Sequence;
        var expected = action == "advance" ? 8 : 16;
        var allowance = ((MoveRegion)ask.Legal).Allowance;
        return Math.Abs(allowance - expected) < 0.001 ? null : $"{action}: allowance {allowance}\", expected {expected}\"";
    }

    /// <summary>Corrode Weapons: the target's next shooting blocks are rolled with no AP (AP(1) less 1).</summary>
    static string? CorrodeWeapons(SpellLog log, Projection final)
    {
        if (FirstGrant(log, "Corrode Weapons") is not var (at, grant)) return "Corrode Weapons never granted";
        var block = log.Payloads.Skip(at + 1).OfType<StepCompleted>().FirstOrDefault(s => s.Step == "roll-to-block" && s.Rolls.Any(r => r.Roll == "defense")
            && log.Frame(s.FrameId).Context.ActorUnitId == grant.UnitId && Shooting(log, s.FrameId));
        if (block is null) return "the target never shot a hit home after the grant";
        var ap = block.Rolls.SelectMany(r => r.Modifiers).Where(m => m.Source == "AP" && m.Amount != 0).ToList();
        return ap.Count == 0 ? null : $"the next shooting blocks carry AP {string.Join(", ", ap.Select(m => m.Amount))}";
    }

    static bool Shooting(SpellLog log, Guid frame)
    {
        for (Guid? f = frame; f is { } id; f = log.ParentOf(id)) if (log.Frame(id).Sequence == "shooting") return true;
        return false;
    }

    /// <summary>Cursed Stride: the target's next activation tests every living model at its Tough value in dice.</summary>
    static string? CursedStride(SpellLog log, Projection final)
    {
        if (FirstGrant(log, "Cursed Stride") is not var (at, grant)) return "Cursed Stride never granted";
        var activation = log.Payloads.Skip(at + 1).OfType<SequenceStarted>().FirstOrDefault(s => RootActions.Contains(s.Sequence) && s.Context.ActorUnitId == grant.UnitId);
        if (activation is null) return "the target never activated after the grant";
        var test = log.Descendants(activation.FrameId).FirstOrDefault(f => f.Sequence == "dangerous-terrain");
        if (test is null) return $"its next activation ({activation.Sequence}) took no dangerous terrain test";
        var dice = log.Steps(test.FrameId).SelectMany(s => s.Rolls).Sum(r => r.Dice.Count);
        var living = Living(log, final, grant.UnitId, log.StartOf(test.FrameId));
        return dice == 6 * living ? null : $"{dice} dice for {living} living Tough(6) models";
    }

    /// <summary>A unit's models with fewer than 6 wounds (p.15 Tough(6): "must take X wounds before being killed") before a log index.</summary>
    static int Living(SpellLog log, Projection final, Guid unit, int before)
    {
        var models = final.Models.Values.Where(m => m.UnitId == unit).Select(m => m.Id).ToList();
        var wounds = models.ToDictionary(m => m, _ => 0);
        foreach (var change in log.Payloads.Take(before).OfType<StepCompleted>().SelectMany(s => s.Changes).OfType<WoundsSet>())
            if (wounds.ContainsKey(change.ModelId)) wounds[change.ModelId] = change.Wounds;
        return wounds.Values.Count(w => w < 6);
    }

    /// <summary>A take_test spell's tests: the spell-test frame, its target, its morale test step and whether it failed.</summary>
    static IReadOnlyList<(SequenceStarted Frame, Guid Target, StepCompleted Test, bool Failed)> Tests(SpellLog log, string spell) =>
        log.Casts(spell).Where(c => c.Passed).SelectMany(c => log.Children(c.Frame).Where(f => f.Sequence == "spell-test")).Select(f =>
        {
            var morale = log.Children(f.FrameId).Single(m => m.Sequence == "morale-test");
            var test = log.Steps(morale.FrameId).Single(s => s.Step == "test");
            return (f, f.Context.TargetUnitIds[0], test, test.Values?.GetValueOrDefault("passed", 1) == 0);
        }).ToList();

    /// <summary>Morale dice cannot be fixed (the test's frame ends in the step that rolls), so the seed gives both outcomes.</summary>
    static string? BothOutcomes(IReadOnlyList<(SequenceStarted Frame, Guid Target, StepCompleted Test, bool Failed)> tests) =>
        tests.Any(t => t.Failed) && tests.Any(t => !t.Failed) ? null : $"the tests all {(tests[0].Failed ? "failed" : "passed")}; the seed must give both";

    /// <summary>Terrifying Fury: a failed test leaves the target Shaken and fatigued; a passed one changes nothing.</summary>
    static string? TerrifyingFury(SpellLog log, Projection final)
    {
        var tests = Tests(log, "Terrifying Fury");
        if (tests.Count == 0) return "Terrifying Fury never resolved";
        foreach (var (frame, target, test, failed) in tests)
        {
            bool Sets(StepCompleted s, string condition) => s.Changes.OfType<ConditionSet>().Any(c => c.Subject.Id == target && c.Condition == condition && c.Present);
            var consequence = log.Steps(frame.FrameId).Single(s => s.Step == "consequence");
            if (failed && !(Sets(test, "shaken") && Sets(consequence, "fatigued"))) return "a failed test did not leave the target Shaken and fatigued";
            if (!failed && Sets(consequence, "fatigued")) return "a passed test made the target fatigued";
        }
        return BothOutcomes(tests);
    }

    /// <summary>Deep Hypnosis: a failed test offers the caster's side a move of the target's models of up to 6"; a passed one offers none.</summary>
    static string? DeepHypnosis(SpellLog log, Projection final)
    {
        var tests = Tests(log, "Deep Hypnosis");
        if (tests.Count == 0) return "Deep Hypnosis never resolved";
        foreach (var (frame, target, _, failed) in tests)
        {
            var moves = log.Payloads.OfType<AskOpened>().Select(a => a.Ask).Where(a => a.FrameId == frame.FrameId && a.Question == "move").ToList();
            if (!failed) { if (moves.Count > 0) return "a passed test offered a move"; continue; }
            var models = final.Models.Values.Where(m => m.UnitId == target).Select(m => m.Id).ToHashSet();
            if (moves.Count != 1 || moves[0].Legal is not MoveRegion region) return $"a failed test offered {moves.Count} moves";
            if (Math.Abs(region.Allowance - 6) > 0.001 || !region.ModelIds.All(models.Contains)) return $"the move allows {region.Allowance}\" over models not all the target's";
        }
        return BothOutcomes(tests);
    }
}
